INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 23, 'theory', 'Квиз: идемпотентная автоматизация');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 0, 'Что значит, что автоматизация идемпотентна?', '["Она всегда выполняется быстрее предыдущего запуска", "Она не пишет ничего в журнал", "Повторный запуск с теми же данными ничего не меняет, changed равен нулю", "Она выполняется только один раз за всё время"]', 2, 'Идемпотентность — свойство результата: когда хост уже в желаемом состоянии, второй запуск ничего не меняет и в отчёте стоит changed=0. Скорость и журнал тут ни при чём.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 1, 'Почему скрипт с голой командой useradd deploy нельзя безопасно запускать повторно?', '["На существующем имени useradd завершается с ошибкой, код 9", "useradd каждый раз создаёт нового пользователя с другим именем", "useradd удаляет домашний каталог при втором запуске", "useradd работает только от обычного пользователя"]', 0, 'Имя уже занято, и man useradd для этого случая указывает код 9. Скрипт, который останавливается на ошибке, упадёт; поэтому сначала проверяют, есть ли пользователь (id), или берут модуль, который сам сравнивает состояние.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 2, 'Две задачи плея сообщили changed и обе уведомили обработчик «restart nginx». Сколько раз он выполнится в Ansible?', '["Дважды, после каждой задачи", "Один раз, в конце секции игры", "Ни разу, пока не вызвана команда restart вручную", "Столько раз, сколько хостов в инвентаре"]', 1, 'Обработчик выполняется один раз, сколько бы задач его ни уведомило, и после секции задач (или раньше по meta: flush_handlers). Число хостов не умножает запуски на одном хосте.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 3, 'Что верно про прогон ansible-playbook с --check?', '["Он гарантированно предсказывает все изменения", "Он всегда выполняет все команды, но не пишет лог", "Он заменяет проверку идемпотентности вторым запуском", "Модуль без поддержки check mode ничего не сообщает и ничего не делает, поэтому прогноз может быть неполным"]', 3, 'Check mode — симуляция: поддерживающие её модули сообщают, что изменили бы, остальные пропускаются. Поэтому прогноз не гарантия, и реальный второй прогон всё равно нужен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 23, 4, 'Задача lineinfile с regexp нашла три подходящие строки, и ни одна не равна нужной. Что произойдёт?', '["Заменятся все три строки", "Строка будет добавлена в конец, три старые останутся", "Заменится только последняя из найденных строк", "Модуль вернёт ошибку неоднозначности"]', 2, 'Документация lineinfile: при нескольких совпадениях заменяется только последняя найденная строка. Добавление в конец происходит лишь когда совпадений нет вовсе.');
